-- Phase 1 auth triggers (docs/DECISIONS.md D-003).
--   * A profile row is created for every new auth user (email OTP or Google).
--   * The profile email follows auth.users when the user changes their email.
--   * Creating a store marks its owner as a creator. Clients cannot set role themselves.
-- All functions are security definer with a pinned search_path and are not callable by clients.
-- Do not edit this file once pushed.

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    new.email,
    nullif(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'), '')
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create or replace function public.handle_user_email_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.profiles set email = new.email where id = new.id;
  return new;
end;
$$;

create trigger on_auth_user_email_changed
  after update of email on auth.users
  for each row
  when (new.email is distinct from old.email and new.email is not null)
  execute function public.handle_user_email_change();

create or replace function public.mark_store_owner_as_creator()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.profiles set role = 'creator' where id = new.owner_id;
  return new;
end;
$$;

create trigger stores_mark_owner_as_creator
  after insert on public.stores
  for each row execute function public.mark_store_owner_as_creator();

revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.handle_user_email_change() from public, anon, authenticated;
revoke all on function public.mark_store_owner_as_creator() from public, anon, authenticated;
